{
  "justification": "Issue salience is dominated by health and care-related concerns (notably the NHS), indicating strong prominence of the Care/Harm foundation across the electorate. Many other salient topics (immigration, crime, defence, inequality, taxation) engage Loyalty, Authority, Equality, Sanctity, and Proportionality, but because the instrument captures salience without directional preferences, their moral direction cannot be determined.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Ageing population/Social care; Mental health/Well-being; Coronavirus/Pandemic diseases; Pollution/Environment/Climate change; Crime/Law and order/Violence/Vandalism (harm to victims).",
      "status": "SCORED",
      "weight": 1.0
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration/Immigrants; Defence/Foreign affairs/International terrorism; UK union/Devolution/Reform; Northern Ireland; Race relations.",
      "status": "AMBIGUOUS",
      "weight": null
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism; Defence/Foreign affairs/International terrorism; Lack of faith in politics/politicians/government; Morality/Individual behaviour/Lifestyle; Drug abuse.",
      "status": "AMBIGUOUS",
      "weight": null
    },
    {
      "foundation": "sanctity",
      "basis": "Pollution/Environment/Climate change; Morality/Individual behaviour/Lifestyle; Drug abuse; Coronavirus/Pandemic diseases; Food production/Farming (naturalness/contamination).",
      "status": "AMBIGUOUS",
      "weight": null
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality; Low pay/Minimum wage/Fair wages; Race relations; Housing; Education/Schools; Pensions/Social security/Benefits.",
      "status": "AMBIGUOUS",
      "weight": null
    },
    {
      "foundation": "proportionality",
      "basis": "Taxation; Unemployment/Factory closure/Lack of industry; Low pay/Minimum wage/Fair wages (reward for contribution); Crime/Law and order (proportional punishment); Privatisation; Nationalisation/Government control.",
      "status": "AMBIGUOUS",
      "weight": null
    }
  ]
}
